// Use Valtheris's complete seven-sheet set for his roster slot.
CHARACTER_SPRITES.valtheris = VALTHERIS_SPRITES;

// Queue accepted character textures and animation sheets by their stable asset keys. scene
// is the Phaser screen that owns the objects, clock and input used here.
export function preloadCharacterSprites(scene){
  for(const {key,url} of textures) if(!scene.textures.exists(key)) scene.load.spritesheet(key,url,{frameWidth:256,frameHeight:256});
}
